const input = $json.body ?? $json;

const text = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const toBoolean = (value) => {
  if (typeof value === 'boolean') return value;
  return ['true', '1', 'yes', 'on'].includes(text(value).toLowerCase());
};

const clinic_name = text(input.clinic_name);
const followup_stage = text(input.followup_stage || 'first_day').toLowerCase();
const visit_end_min_hours_ago = Number(input.visit_end_min_hours_ago ?? 18);
const visit_end_max_hours_ago = Number(input.visit_end_max_hours_ago ?? 30);
const response_deadline_hours = Number(input.response_deadline_hours ?? 24);
const channel = text(input.channel || 'whatsapp').toLowerCase();
const limit = Number(input.limit ?? 100);
const confirm_generation = toBoolean(input.confirm_generation);

const errors = [];

if (!clinic_name) {
  errors.push({
    field: 'clinic_name',
    message: 'نام کلینیک الزامی است.',
  });
}

if (!['first_day', 'third_day', 'seventh_day', 'custom'].includes(followup_stage)) {
  errors.push({
    field: 'followup_stage',
    message: 'مرحله پیگیری معتبر نیست.',
  });
}

if (
  !Number.isInteger(visit_end_min_hours_ago) ||
  visit_end_min_hours_ago < 0 ||
  visit_end_min_hours_ago > 2160
) {
  errors.push({
    field: 'visit_end_min_hours_ago',
    message: 'حداقل فاصله از پایان مراجعه باید بین 0 و 2160 ساعت باشد.',
  });
}

if (
  !Number.isInteger(visit_end_max_hours_ago) ||
  visit_end_max_hours_ago < 1 ||
  visit_end_max_hours_ago > 2160 ||
  visit_end_max_hours_ago <= visit_end_min_hours_ago
) {
  errors.push({
    field: 'visit_end_max_hours_ago',
    message: 'حداکثر فاصله باید از حداقل بیشتر و حداکثر 2160 ساعت باشد.',
  });
}

if (
  !Number.isInteger(response_deadline_hours) ||
  response_deadline_hours < 1 ||
  response_deadline_hours > 168
) {
  errors.push({
    field: 'response_deadline_hours',
    message: 'مهلت پاسخ باید بین 1 و 168 ساعت باشد.',
  });
}

if (!['whatsapp', 'sms', 'phone', 'telegram', 'web', 'manual'].includes(channel)) {
  errors.push({
    field: 'channel',
    message: 'کانال پیگیری معتبر نیست.',
  });
}

if (!Number.isInteger(limit) || limit < 1 || limit > 500) {
  errors.push({
    field: 'limit',
    message: 'limit باید یک عدد صحیح بین 1 و 500 باشد.',
  });
}

if (confirm_generation !== true) {
  errors.push({
    field: 'confirm_generation',
    message: 'ایجاد پیگیری‌ها باید به‌صورت صریح تأیید شود.',
  });
}

return [{
  json: {
    clinic_name,
    followup_stage,
    visit_end_min_hours_ago,
    visit_end_max_hours_ago,
    response_deadline_hours,
    channel,
    limit,
    confirm_generation,
    validation_status: errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];

return [{
  json: {
    success: false,
    result: 'invalid_request',
    message: 'اطلاعات تولید پیگیری پس از مراجعه ناقص یا نامعتبر است.',
    followup_count: 0,
    followups: [],
    errors: $json.errors ?? [],
  },
}];
